             dict(name="столбы в землю", block="бур сломался на третьем столбе", fact="двенадцать столбов стоят ровно", have=[], paths=["бур в прокате в райцентре", "лом и лопата, дольше на день", "у соседа по даче мотобур", "Михалыч чинит бур в гараже за вечер"]),
