# ---- титул, подписи, заметки под легенду 30+
COVER = K.COVER.replace('<h1>СБОРНИК ТРЕНИРОВОЧНЫХ ЗАДАНИЙ<br>«ТРИ ПУТИ»</h1>',
                        '<h1>СБОРНИК ТРЕНИРОВОЧНЫХ ЗАДАНИЙ<br>«ТРИ ПУТИ»</h1><p class="sub" style="margin-top:-8mm">Редакция 3 · легенда курсанта 30+</p>')
s5 = (K.stage5().replace("Курсант, 19 лет", "Курсант, 34 года")
      .replace("«чтобы мотоцикл завёлся» — это «Надо», а «быть на зачёте к девяти» — фактически",
               "«чтобы машина завелась» — это «Надо», а «Маша в саду, курсант на защите к 9:30» — фактически"))
s6 = K.stage6().replace("Курсант, 19 лет", "Курсант, 34 года")
assert "мотоцикл" not in s5 and "мотоцикл" not in s6, "остался мотоцикл из легенды 19 лет"
assert "19 лет" not in s5 and "19 лет" not in s6

HTML = (f'<!DOCTYPE html><html lang="ru"><head><meta charset="utf-8"><title>Сборник «Три пути» · редакция 3</title>{K.CSS}</head><body>'
        f'{COVER}{K.GENERAL}{K.stage1()}{K.stage2()}{K.stage3()}{K.stage4()}{s5}{s6}{K.vedomost()}</body></html>')
for bad in ("школьная библиотека", "почта учителя", "реферат", "прихода родителей", "позвонить матери", "пицц"):
    assert bad not in HTML, bad
open(f"{SP}/kursant_30.html", "w", encoding="utf-8").write(HTML)
print("этап V:", len(K.L5), "этап VI:", len(K.L6), "| html", len(HTML))
